// Find DD tasks and validate prerequisites
const tasks = $input.first().json.result || [];
console.log(`🔍 Scanning ${tasks.length} Kanboard tasks for Due Diligence`);

// Find DD tasks that haven't been processed
let ddTask = null;
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Check if it's a DD task
  if (title.toLowerCase().includes('due diligence:')) {
    // Check if it hasn't been completed yet
    if (!description.includes('✅ DD Report Completed')) {
      ddTask = task;
      break;
    }
  }
}

if (!ddTask) {
  console.log('ℹ️ No pending Due Diligence tasks found');
  throw new Error('No pending Due Diligence tasks found');
}

console.log(`🎯 Processing DD Task: ${ddTask.title}`);

// Validate prerequisites
const errors = [];
const title = ddTask.title || '';
const description = ddTask.description || '';

// Extract company name
const companyMatch = title.match(/due diligence:\s*(.+)/i);
const companyName = companyMatch ? companyMatch[1].trim() : '';
if (!companyName) {
  errors.push('Title must be "Due Diligence: [Company Name]"');
}

// Extract website URL
const urlMatch = description.match(/https?:\/\/[^\s]+/);
const websiteUrl = urlMatch ? urlMatch[0] : '';
if (!websiteUrl) {
  errors.push('Description must contain official website URL');
}

// Check for attachments (we'll validate PDF attachments in next step)
if (!ddTask.attachments || ddTask.attachments.length === 0) {
  console.log('⚠️ Warning: No attachments found. Will check via API.');
}

if (errors.length > 0) {
  console.log(`❌ Validation errors: ${errors.join(', ')}`);
  throw new Error(`Task validation failed: ${errors.join(', ')}`);
}

return {
  json: {
    task_id: ddTask.id,
    project_id: ddTask.project_id || 1,
    title: title,
    description: description,
    company_name: companyName,
    website_url: websiteUrl,
    raw_task: ddTask
  }
};

// Validate PDF attachments and prepare for processing
const taskData = $('Find & Validate DD Task').first().json;
const attachmentsResponse = $input.first().json;
const attachments = attachmentsResponse.result || [];

console.log(`📎 Found ${attachments.length} attachments`);

// Filter PDF attachments
const pdfAttachments = attachments.filter(file => 
  file.name && file.name.toLowerCase().endsWith('.pdf')
);

if (pdfAttachments.length === 0) {
  throw new Error('No PDF attachments found. Due Diligence requires PDF documents.');
}

console.log(`📄 Found ${pdfAttachments.length} PDF attachments:`);
pdfAttachments.forEach(pdf => console.log(`  - ${pdf.name}`));

return {
  json: {
    ...taskData,
    pdf_attachments: pdfAttachments,
    total_pdfs: pdfAttachments.length,
    processing_status: 'attachments_validated'
  }
};

// Initialize local knowledge base for this task
const taskData = $input.first().json;
const companyName = taskData.company_name;
const taskId = taskData.task_id;

// Create a knowledge base object to store all processed content
const knowledgeBase = {
  company_name: companyName,
  task_id: taskId,
  website_content: null,
  pdf_contents: [],
  financial_analysis: [],
  non_financial_analysis: [],
  sections_completed: [],
  processing_status: 'initialized',
  created_at: new Date().toISOString()
};

// Store initial KB in workflow context
console.log(`📋 Created local knowledge base for ${companyName}`);

// Check if we need to process documents or if they're already processed
const needsProcessing = true; // Always process for now, can add smart checking later

return {
  json: {
    ...taskData,
    knowledge_base: knowledgeBase,
    needs_document_processing: needsProcessing,
    processing_phase: 'kb_initialized'
  }
};

// Process each PDF attachment
const taskData = $('Validate PDF Attachments').first().json;
const pdfs = taskData.pdf_attachments;

const results = [];
for (let i = 0; i < pdfs.length; i++) {
  const pdf = pdfs[i];
  results.push({
    json: {
      ...taskData,
      current_pdf: pdf,
      pdf_index: i,
      pdf_name: pdf.name,
      pdf_id: pdf.id,
      pdf_url: `http://localhost:8000/files/${pdf.id}`
    }
  });
}

return results;

// Categorize content as financial or non-financial
const pdfData = $input.first().json;
const extractedText = pdfData.response || '';
const pdfName = $('Split PDF Processing').first().json.pdf_name.toLowerCase();

// Financial document indicators
const financialKeywords = [
  'financial statement', 'balance sheet', 'income statement', 'cash flow',
  'profit and loss', 'p&l', 'revenue', 'expenses', 'assets', 'liabilities',
  'equity', 'financial report', 'audit', 'accounting', 'budget', 'forecast',
  'ebitda', 'net income', 'gross margin', 'operating margin', 'quarterly',
  'annual report', 'sec filing', '10-k', '10-q', 'earnings', 'investment'
];

const textLower = extractedText.toLowerCase();
const isFinancial = financialKeywords.some(keyword => 
  textLower.includes(keyword) || pdfName.includes(keyword)
);

console.log(`📊 Document ${$('Split PDF Processing').first().json.pdf_name} categorized as: ${isFinancial ? 'FINANCIAL' : 'NON-FINANCIAL'}`);

return {
  json: {
    ...$('Split PDF Processing').first().json,
    extracted_text: extractedText,
    is_financial: isFinancial,
    content_category: isFinancial ? 'financial' : 'non-financial',
    processing_ready: true
  }
};

